# SPDX-FileCopyrightText: 2026 José M. Requena Plens
# SPDX-License-Identifier: MIT
"""Every file that can carry a comment carries both REUSE lines, copyright first.

The Kleidos header rule (owner, 2026-11-22; docs/quality.md in
kleidos-dev/.github, "Licensing headers"). A file whose format has a comment
syntax starts with two lines in that syntax, in this order:

    <copyright tag> <year> José M. Requena Plens
    <license tag> <the repository's SPDX expression for the file>

where the tags are REUSE's file-copyright and license-identifier tags, and
<year> is the year of the file's first commit, as
`git log --diff-filter=A --format=%ad --date=format:%Y -- <file>` gives it
(the current year for a file not committed yet). No e-mail address. A file
that cannot carry a comment (images, JSON, binaries, generated data) gets
both through a REUSE.toml annotation instead; so does a file REUSE.toml
covers with precedence "override" (third-party text, a template whose
comments would leak into what GitHub shows). `reuse lint` then proves that
every file has both.

Usage:
    spdx_headers.py [--repo DIR]                 check; exit 1 on any problem
    spdx_headers.py --write [--repo DIR] [--license EXPR] [PATH ...]
        insert or repair the two lines; the license comes from the file's
        own line, else from the REUSE.toml annotation that covers it, else
        from --license

Byte copies of the quality kit (listed in .github/quality/SOURCE.json) carry
the kit's year and are checked for the two lines only; the commit-message
gate copied from kleidos-dev/agents is checked there. In a shallow clone the
years cannot be read, so only their presence is checked (the CI fetches the
whole history).

Python 3.11 or newer, standard library only.
"""

from __future__ import annotations

import argparse
import datetime as dt
import fnmatch
import json
import os
import re
import subprocess
import sys
import tomllib
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any

HOLDER = "José M. Requena Plens"
# Written in two halves so that REUSE does not read this module's own text
# as a header.
COPYRIGHT_TAG = "SPDX-" + "FileCopyrightText:"
LICENSE_TAG = "SPDX-" + "License-Identifier:"
IGNORE_START = "REUSE-" + "IgnoreStart"
IGNORE_END = "REUSE-" + "IgnoreEnd"
HEAD_LINES = 40

# The comment syntax of each format, by suffix and by file name.
LINE = {"#": "# ", "//": "// ", "--": "-- ", "%": "% ", ";": "; "}
HASH_SUFFIXES = {
    ".py",
    ".pyi",
    ".sh",
    ".bash",
    ".zsh",
    ".yml",
    ".yaml",
    ".toml",
    ".cfg",
    ".ini",
    ".conf",
    ".properties",
    ".in",
    ".mk",
    ".cmake",
    ".tcl",
    ".r",
    ".pl",
    ".rb",
    ".ps1",
    ".nix",
    ".dockerfile",
    ".lf",  # ESP-IDF linker fragments
    ".supp",  # sanitizer and valgrind suppressions
}
HASH_NAMES = {
    ".gitignore",
    ".gitattributes",
    ".gitmodules",
    ".gitleaksignore",
    ".git-blame-ignore-revs",
    ".coveragerc",
    ".editorconfig",
    ".shellcheckrc",
    "shellcheckrc",
    ".cppcheck-suppress",
    ".clang-tidy",
    ".clang-format",
    ".yamllint",
    ".npmrc",
    "Makefile",
    "Dockerfile",
    "CMakeLists.txt",
    "CODEOWNERS",
    "Doxyfile",
}
# Names whose format takes # comments: ESP-IDF's sdkconfig fragments and
# Kconfig files, and its partition tables (the one .csv that carries comments).
HASH_NAME_PATTERN = re.compile(
    r"^(?:sdkconfig(?:[.\w-]*)|Kconfig(?:[.\w-]*)|partitions[\w.-]*\.csv)$"
)
SLASH_SUFFIXES = {
    ".js",
    ".mjs",
    ".cjs",
    ".ts",
    ".tsx",
    ".mts",
    ".cts",
    ".jsx",
    ".jsonc",
    ".json5",
    ".c",
    ".cc",
    ".cpp",
    ".cxx",
    ".h",
    ".hh",
    ".hpp",
    ".hxx",
    ".ino",
    ".go",
    ".rs",
    ".java",
    ".kt",
    ".swift",
    ".scad",
    ".dot",
    ".proto",
    ".dox",  # Doxygen pages, parsed as C++
}
BLOCK_SUFFIXES = {".css", ".scss", ".less", ".ld"}
# Case matters: .S is assembly run through the C preprocessor, which takes
# C comments; a plain .s is the assembler's own syntax and is left alone.
BLOCK_SUFFIXES_EXACT = {".S"}
HTML_SUFFIXES = {".md", ".markdown", ".html", ".htm", ".xml", ".vue"}
# An Astro component's header goes in its front matter, as // lines: an HTML
# comment in its template would reach every page that renders it.
ASTRO_SUFFIXES = {".astro"}
DASH_SUFFIXES = {".sql", ".lua"}
PERCENT_SUFFIXES = {".tex", ".sty"}
# requirements*.txt take # comments; other .txt files are data.
REQUIREMENTS = re.compile(r"^requirements[\w.-]*\.txt$")
# Lockfiles are generated by their package managers, which drop comments:
# REUSE.toml states them.
LOCKFILES = re.compile(
    r"^(pnpm-lock\.yaml|yarn\.lock|uv\.lock|poetry\.lock|Cargo\.lock|Gemfile\.lock"
    r"|package-lock\.json|dependencies\.lock(\..*)?)$"
)
# Files REUSE itself ignores.
REUSE_IGNORED = re.compile(r"^(LICEN[CS]E|COPYING)([-.].*)?$|^REUSE\.toml$")
# Kept out of a file because GitHub copies its text into what people write:
# a header there would land in every pull request or issue body.
COPIED_INTO_POSTS = {
    ".github/PULL_REQUEST_TEMPLATE.md",
    ".github/pull_request_template.md",
    "PULL_REQUEST_TEMPLATE.md",
    "pull_request_template.md",
}
COMMIT_CHECK_COPIES = (
    ".github/commit-check/check_commit_msg.py",
    ".github/workflows/commit-check.yml",
    ".github/workflows/commit-check-comment.yml",
)
AGENTS_COPY_MARK = "Vendored from kleidos-dev/agents"
EMAIL = re.compile(r"<[^>@\s]+@[^>\s]+>|\b[\w.+-]+@[\w-]+\.[\w.-]+\b")
YEAR_LEAD = re.compile(r"^(\d{4})(?:\s*[-,]\s*\d{4})*\s+(.*)$")
FRONT_MATTER = re.compile(r"\A---\r?\n.*?\r?\n---\r?\n", re.S)


@dataclass(frozen=True)
class Style:
    """How one format writes a comment."""

    kind: str  # "line", "block", "html" or "astro"
    prefix: str = ""

    def header(self, copyright_text: str, license_expr: str) -> list[str]:
        c = f"{COPYRIGHT_TAG} {copyright_text}"
        lic = f"{LICENSE_TAG} {license_expr}"
        if self.kind in ("line", "astro"):
            return [f"{self.prefix}{c}\n", f"{self.prefix}{lic}\n"]
        if self.kind == "block":
            return ["/*\n", f" * {c}\n", f" * {lic}\n", " */\n"]
        return ["<!--\n", f"{c}\n", f"{lic}\n", "-->\n"]


# Interpreters whose scripts take # comments after the shebang (a Node.js
# script does not: its file stays with REUSE.toml unless its name says .js).
HASH_SHEBANG = re.compile(
    r"#!\s*\S*?(?:/env\s+(?:-\S+\s+)*)?(?:\S*/)?(?:bash|zsh|ksh|dash|sh)\b"
    r"|#!\s*\S*?(?:/env\s+(?:-\S+\s+)*)?(?:\S*/)?(?:python[\d.]*|perl|ruby|tclsh)\b"
)


def style_for(rel: str, text: str | None = None) -> Style | None:
    """The comment syntax of a path, or None when its format has none.

    A file of no known format that starts with a shebang is a script and
    takes # comments.
    """
    style = _style_by_name(rel)
    if style is None and text is not None and HASH_SHEBANG.match(text):
        return Style("line", LINE["#"])
    return style


def _style_by_name(rel: str) -> Style | None:
    p = PurePosixPath(rel)
    name, suffix = p.name, p.suffix.lower()
    if (
        suffix in HASH_SUFFIXES
        or name in HASH_NAMES
        or REQUIREMENTS.match(name)
        or HASH_NAME_PATTERN.match(name)
    ):
        return Style("line", LINE["#"])
    if p.suffix in BLOCK_SUFFIXES_EXACT:
        return Style("block")
    if suffix in ASTRO_SUFFIXES:
        return Style("astro", LINE["//"])
    if suffix in SLASH_SUFFIXES:
        return Style("line", LINE["//"])
    if suffix in DASH_SUFFIXES:
        return Style("line", LINE["--"])
    if suffix in PERCENT_SUFFIXES:
        return Style("line", LINE["%"])
    if suffix in BLOCK_SUFFIXES:
        return Style("block")
    if suffix in HTML_SUFFIXES:
        return Style("html")
    return None


# --------------------------------------------------------------------------
# REUSE.toml


def _as_list(value: Any) -> list[str]:
    if value is None:
        return []
    return [value] if isinstance(value, str) else [str(v) for v in value]


def _glob(pattern: str, path: str) -> bool:
    """REUSE.toml's globs: * within a segment, ** across segments.

    As REUSE translates them, a / right after ** is part of the globstar, so
    `**/*.json` also matches a file at the root.
    """
    regex = ""
    i = 0
    while i < len(pattern):
        if pattern.startswith("**/", i):
            regex += ".*"
            i += 3
        elif pattern.startswith("**", i):
            regex += ".*"
            i += 2
        elif pattern[i] == "*":
            regex += "[^/]*"
            i += 1
        else:
            regex += re.escape(pattern[i])
            i += 1
    return re.fullmatch(regex, path) is not None


def reuse_annotations(root: Path) -> list[dict[str, Any]]:
    path = root / "REUSE.toml"
    if not path.is_file():
        return []
    return list(tomllib.loads(path.read_text(encoding="utf-8")).get("annotations") or [])


def annotation_for(tables: list[dict[str, Any]], rel: str) -> dict[str, Any] | None:
    """The last annotation that covers a path (REUSE: the last one wins)."""
    chosen = None
    for table in tables:
        if any(_glob(p, rel) for p in _as_list(table.get("path"))):
            chosen = table
    return chosen


# --------------------------------------------------------------------------
# The repository


def git(root: Path, *args: str) -> str:
    return subprocess.run(
        ["git", "-C", str(root), *args], capture_output=True, check=True, text=True
    ).stdout


def tracked(root: Path) -> list[str]:
    out = git(root, "ls-files", "-z", "--cached", "--others", "--exclude-standard")
    return sorted(p for p in out.split("\0") if p and (root / p).is_file())


def is_shallow(root: Path) -> bool:
    return git(root, "rev-parse", "--is-shallow-repository").strip() == "true"


def first_years(root: Path) -> dict[str, str]:
    """Path -> the year, in UTC, of the commit that first added it (oldest wins)."""
    out = subprocess.run(
        [
            "git",
            "-C",
            str(root),
            "log",
            "--diff-filter=A",
            "--no-renames",
            "--format=%x00%ad",
            "--date=format-local:%Y",
            "--name-only",
        ],
        capture_output=True,
        check=True,
        text=True,
        env={**os.environ, "TZ": "UTC"},
    ).stdout
    years: dict[str, str] = {}
    for chunk in out.split("\0"):
        lines = [ln for ln in chunk.splitlines() if ln.strip()]
        if not lines:
            continue
        year, names = lines[0].strip(), lines[1:]
        for name in names:
            years[name] = year  # log runs newest first, so the oldest is written last
    return years


def kit_copies(root: Path) -> set[str]:
    path = root / ".github" / "quality" / "SOURCE.json"
    if not path.is_file():
        return set()
    try:
        return {str(e["path"]) for e in json.loads(path.read_text(encoding="utf-8"))["files"]}
    except (ValueError, KeyError, TypeError):
        return set()


def agents_copy(root: Path, rel: str) -> bool:
    """A file of the commit-message gate that is still kleidos-dev/agents' copy."""
    if rel.endswith(".py"):
        return True
    try:
        return AGENTS_COPY_MARK in (root / rel).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False


# --------------------------------------------------------------------------
# One file


@dataclass
class Header:
    copyright_lines: list[tuple[int, str]]  # (line index, text after the tag)
    license_lines: list[tuple[int, str]]


def read_header(lines: list[str]) -> Header:
    """The copyright and license tags in a file's head, outside ignore blocks."""
    head = Header([], [])
    ignoring = False
    for i, line in enumerate(lines[:HEAD_LINES]):
        if IGNORE_START in line:
            ignoring = True
        if IGNORE_END in line:
            ignoring = False
            continue
        if ignoring:
            continue
        for tag, bucket in (
            (COPYRIGHT_TAG, head.copyright_lines),
            (LICENSE_TAG, head.license_lines),
        ):
            at = line.find(tag)
            if at != -1:
                value = line[at + len(tag) :].strip()
                for closer in ("*/", "-->"):  # a header on one line of a block comment
                    value = value.removesuffix(closer).rstrip()
                bucket.append((i, value))
    return head


def years_accepted(year: str) -> tuple[str, str]:
    """The header years a file first committed in `year` may carry.

    The year itself, or the one before: a pull request written in December
    and squash-merged in January lands on main with a January commit, and
    its header (written when the file was) must not turn main red.
    """
    return year, str(int(year) - 1)


def _inside_leading_comment(rest: str, opener: str, closer: str) -> bool:
    """Whether `rest` is only whole comments and then one comment still open."""
    rest = rest.lstrip()
    open_at = rest.rfind(opener)
    if not rest.startswith(opener) or closer in rest[open_at:]:
        return False
    earlier = re.sub(re.escape(opener) + ".*?" + re.escape(closer), "", rest[:open_at], flags=re.S)
    return not earlier.strip()


def header_misplaced(lines: list[str], style: Style, index: int) -> str | None:
    """Why the header line at `index` is not in a comment at the top, or None."""
    before = "".join(lines[:index])
    line = lines[index] if index < len(lines) else ""
    at = min((line.find(t) for t in (COPYRIGHT_TAG, LICENSE_TAG) if t in line), default=0)
    if style.kind == "astro":
        front = FRONT_MATTER.match("".join(lines))
        if not front or len(before) + len(line) > front.end():
            return "an Astro component's header goes in its front matter, as // lines"
        body = before.split("\n", 1)[1] if "\n" in before else ""
        if any(ln.strip() and not ln.lstrip().startswith("//") for ln in body.splitlines()):
            return "the header lines come first in the front matter"
        return None
    if style.kind == "line":
        mark = style.prefix.strip()
        for i, ln in enumerate(lines[:index]):
            bare = ln.strip()
            shebang = i == 0 and bare.startswith("#!")
            if bare and not bare.startswith(mark) and bare != "---" and not shebang:
                return "the header lines sit in a comment at the top of the file"
        if not line.lstrip().startswith(mark):
            return "the header lines sit in a comment at the top of the file"
        return None
    if style.kind == "html":
        front = FRONT_MATTER.match(before)
        rest = before[front.end() :] if front else before
        rest = re.sub(r"\A\s*<\?xml[^>]*\?>", "", rest)
        rest = re.sub(r"\A\s*<!DOCTYPE[^>]*>", "", rest, flags=re.IGNORECASE)
        if not _inside_leading_comment(rest + line[:at], "<!--", "-->"):
            return "the header lines sit in an HTML comment at the top of the file"
        return None
    if not _inside_leading_comment(before + line[:at], "/*", "*/"):
        return "the header lines sit in a block comment at the top of the file"
    return None


def check_text(rel: str, text: str, year: str | None, *, copy: bool = False) -> list[str]:
    """What is wrong with one file's header (empty when it is right)."""
    lines = text.splitlines(keepends=True)
    head = read_header(lines)
    problems = []
    style = style_for(rel, text)
    if not head.copyright_lines:
        problems.append(f"no {COPYRIGHT_TAG} line in its first {HEAD_LINES} lines")
    if not head.license_lines:
        problems.append(f"no {LICENSE_TAG} line in its first {HEAD_LINES} lines")
    if (
        head.copyright_lines
        and head.license_lines
        and head.copyright_lines[0][0] > head.license_lines[0][0]
    ):
        problems.append("the copyright line comes after the license line: copyright first")
    for _i, value in head.copyright_lines:
        if EMAIL.search(value):
            problems.append(f"the copyright line carries an e-mail address: {value!r}")
        m = YEAR_LEAD.match(value)
        if not m:
            problems.append(f"the copyright line does not start with a year: {value!r}")
            continue
        if (
            HOLDER in m.group(2)
            and year is not None
            and not copy
            and m.group(1) not in years_accepted(year)
        ):
            problems.append(
                f"the copyright year is {m.group(1)}, but git first added the file in {year}"
            )
    if head.copyright_lines and not any(HOLDER in v for _i, v in head.copyright_lines):
        problems.append(
            f"no copyright line names {HOLDER} (a third-party file is stated in REUSE.toml"
            ' with precedence "override")'
        )
    if style is not None:
        for index in sorted({i for i, _v in head.copyright_lines + head.license_lines}):
            why = header_misplaced(lines, style, index)
            if why:
                problems.append(why)
                break
    return problems


def insert_at(lines: list[str]) -> int:
    """Where a new header goes: after a shebang, an encoding line, an XML declaration."""
    at = 0
    if lines and lines[0].startswith("#!"):
        at = 1
    if len(lines) > at and re.match(r"^#.*coding[:=]", lines[at]):
        at += 1
    if lines and lines[0].startswith("<?xml"):
        at = 1
    return at


def _sibling_line(line: str, tag: str, text: str) -> str:
    """A new header line shaped like `line`: same prefix, same closer if it closes there."""
    prefix = line[: line.find(tag)]
    stripped = line.rstrip()
    closer = next((c for c in ("-->", "*/") if stripped.endswith(c)), "")
    if closer and closer not in prefix:
        # A one-line comment (<!-- tag value -->): the new line is one too.
        return f"{prefix}{text} {closer}\n"
    return f"{prefix}{text}\n"


def _lift_astro_header(text: str, license_expr: str | None) -> tuple[str, str | None]:
    """Remove header lines an Astro file carries outside its front matter.

    Returns the text without them (and without an HTML comment they leave
    empty) and the license they named, so the writer puts both lines back
    at the top of the front matter.
    """
    lines = text.splitlines(keepends=True)
    head = read_header(lines)
    style = Style("astro", LINE["//"])
    found = head.copyright_lines + head.license_lines
    if not any(header_misplaced(lines, style, i) for i, _v in found):
        return text, license_expr
    if any(HOLDER not in v for _i, v in head.copyright_lines):
        return text, license_expr  # another holder's notice: a person moves it
    if head.license_lines:
        license_expr = head.license_lines[0][1]
    drop = {i for i, _v in found}
    kept = "".join(ln for i, ln in enumerate(lines) if i not in drop)
    kept = re.sub(r"<!--\s*-->\n?", "", kept)
    return kept, license_expr


def fix_text(rel: str, text: str, year: str, license_expr: str | None) -> tuple[str, str | None]:
    """The text with a correct header, and why it could not be fixed (or None)."""
    style = style_for(rel, text)
    if style is None:
        return text, "its format has no comment syntax: state it in REUSE.toml"
    if style.kind == "astro":
        text, license_expr = _lift_astro_header(text, license_expr)
    lines = text.splitlines(keepends=True)
    if lines and not lines[-1].endswith("\n"):
        lines[-1] += "\n"
    head = read_header(lines)
    owner = f"{year} {HOLDER}"
    # Repair copyright lines in place: drop e-mails, set the owner's year.
    for i, value in head.copyright_lines:
        new_value = EMAIL.sub("", value).strip()
        m = YEAR_LEAD.match(new_value)
        if m and HOLDER in m.group(2):
            new_value = owner
        if new_value != value:
            lines[i] = lines[i].replace(value, new_value, 1)
    head = read_header(lines)
    if head.license_lines and not head.copyright_lines:
        i = head.license_lines[0][0]
        lines.insert(i, _sibling_line(lines[i], LICENSE_TAG, f"{COPYRIGHT_TAG} {owner}"))
        return "".join(lines), None
    if head.license_lines and head.copyright_lines:
        if head.copyright_lines[0][0] > head.license_lines[0][0]:
            ci = head.copyright_lines[0][0]
            li = head.license_lines[0][0]
            lines[ci], lines[li] = lines[li], lines[ci]
        return "".join(lines), None
    if head.copyright_lines and not head.license_lines:
        if not license_expr:
            return text, "no license: give --license or cover the file in REUSE.toml"
        i = head.copyright_lines[-1][0]
        lines.insert(i + 1, _sibling_line(lines[i], COPYRIGHT_TAG, f"{LICENSE_TAG} {license_expr}"))
        return "".join(lines), None
    if not license_expr:
        return text, "no license: give --license or cover the file in REUSE.toml"
    new = style.header(owner, license_expr)
    if style.kind == "astro":
        front = FRONT_MATTER.match(text)
        if front:
            opening = front.group(0).split("\n", 1)[0] + "\n"
            inner = front.group(0)[len(opening) :]
            return opening + "".join(new) + inner + text[front.end() :], None
        return "---\n" + "".join(new) + "---\n" + text, None
    if style.kind == "html":
        front = FRONT_MATTER.match(text)
        if front:
            body = text[front.end() :]
            return front.group(0) + "".join(new) + "\n" + body.lstrip("\n"), None
        # An XML declaration stays the first line.
        decl = lines[:1] if lines and lines[0].startswith("<?xml") else []
        rest = "".join(lines[len(decl) :]).lstrip("\n")
        return "".join(decl) + "".join(new) + "\n" + rest, None
    at = insert_at(lines)
    after = lines[at] if at < len(lines) else ""
    joiner: list[str] = []
    if after.strip():
        is_comment = style.kind == "line" and after.lstrip().startswith(style.prefix.strip())
        joiner = [style.prefix.rstrip() + "\n"] if is_comment else ["\n"]
    lines[at:at] = [*new, *joiner]
    return "".join(lines), None


# --------------------------------------------------------------------------
# The repository-wide check and write


@dataclass
class Plan:
    """The files the rule applies to, and how."""

    full: list[str]  # checked for both lines and the year
    presence: list[str]  # byte copies: both lines, the year is their source's
    skipped: dict[str, str]  # path -> why it is not checked
    unknown: list[str]  # text files of a format this module has no syntax for


def text_of(root: Path, rel: str) -> str | None:
    """A file's text, or None for a binary (a NUL byte, or not UTF-8)."""
    data = (root / rel).read_bytes()
    if b"\0" in data:
        return None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return None


def is_catch_all(table: dict[str, Any]) -> bool:
    """A REUSE.toml annotation that covers every path (`**`)."""
    return any(p in ("**", "**/*") for p in _as_list(table.get("path")))


def plan(root: Path) -> Plan:
    tables = reuse_annotations(root)
    specific = [t for t in tables if not is_catch_all(t)]
    copies = kit_copies(root)
    full: list[str] = []
    presence: list[str] = []
    skipped: dict[str, str] = {}
    unknown: list[str] = []
    for rel in tracked(root):
        p = PurePosixPath(rel)
        if p.parts[0] in ("LICENSES", ".reuse") or REUSE_IGNORED.match(p.name):
            continue
        if "node_modules" in p.parts or LOCKFILES.match(p.name):
            continue
        if rel in COMMIT_CHECK_COPIES and agents_copy(root, rel):
            skipped[rel] = "a copy of kleidos-dev/agents' commit-message gate: checked there"
            continue
        if _style_by_name(rel) is None:
            text = text_of(root, rel)
            if text is None or annotation_for(specific, rel) is not None:
                continue  # REUSE.toml states it; reuse lint checks that it does
            if style_for(rel, text) is None:
                unknown.append(rel)
                continue
        table = annotation_for(tables, rel)
        if table is not None and table.get("precedence") == "override":
            skipped[rel] = 'stated in REUSE.toml with precedence "override"'
            continue
        if rel in COPIED_INTO_POSTS:
            skipped[rel] = "GitHub copies it into posts: REUSE.toml states it"
            continue
        (presence if rel in copies else full).append(rel)
    return Plan(full, presence, skipped, unknown)


def check_repo(root: Path, today: dt.date | None = None) -> tuple[list[str], list[str]]:
    """(problems, notes) for every file the rule applies to."""
    today = today or dt.datetime.now(tz=dt.UTC).date()
    work = plan(root)
    notes = []
    shallow = is_shallow(root)
    years = {} if shallow else first_years(root)
    if shallow:
        notes.append("shallow clone: the years were not checked (fetch the whole history)")
    problems: list[str] = []
    problems.extend(
        f"{rel}: a text file in a format the header check has no comment syntax for: add the"
        " syntax to the kit's spdx_headers.py, or name the file (or its format, **/*.json) in"
        " a REUSE.toml annotation other than the catch-all"
        for rel in work.unknown
    )
    for rel in COPIED_INTO_POSTS:
        if (root / rel).is_file() and style_for(rel) is not None:
            table = annotation_for(reuse_annotations(root), rel)
            if table is None:
                problems.append(f"{rel}: REUSE.toml must state its copyright and license")
    for rel in work.full + work.presence:
        try:
            text = (root / rel).read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue  # binary under a text suffix: REUSE.toml's to state
        year = None if shallow else years.get(rel, str(today.year))
        problems.extend(
            f"{rel}: {p}" for p in check_text(rel, text, year, copy=rel in work.presence)
        )
    problems.extend(
        f"REUSE.toml: a copyright carries an e-mail address: {value!r}"
        for table in reuse_annotations(root)
        for value in _as_list(table.get(COPYRIGHT_TAG.rstrip(":")))
        if EMAIL.search(value)
    )
    notes.append(
        f"{len(work.full)} file(s) checked in full, {len(work.presence)} kit copies for"
        f" presence, {len(work.skipped)} skipped"
    )
    return problems, notes


def license_for(root: Path, rel: str, default: str | None) -> str | None:
    table = annotation_for(reuse_annotations(root), rel)
    if table is not None:
        found = _as_list(table.get(LICENSE_TAG.rstrip(":")))
        if found:
            return " AND ".join(found) if len(found) > 1 else found[0]
    return default


def write_repo(
    root: Path, paths: list[str] | None, default_license: str | None, today: dt.date | None = None
) -> tuple[list[str], list[str]]:
    """(files changed, problems left) after inserting or repairing headers."""
    today = today or dt.datetime.now(tz=dt.UTC).date()
    if is_shallow(root):
        raise SystemExit("spdx_headers: a shallow clone has no first-commit years; fetch it whole")
    years = first_years(root)
    work = plan(root)
    targets = work.full
    if paths:
        wanted = {PurePosixPath(p).as_posix() for p in paths}
        targets = [r for r in targets if r in wanted or any(fnmatch.fnmatch(r, w) for w in wanted)]
    changed, left = [], []
    for rel in targets:
        path = root / rel
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        year = years.get(rel, str(today.year))
        if not check_text(rel, text, year):
            continue
        new, why = fix_text(rel, text, year, license_for(root, rel, default_license))
        if why:
            left.append(f"{rel}: {why}")
            continue
        if new != text:
            path.write_text(new, encoding="utf-8")
            changed.append(rel)
        remaining = check_text(rel, new, year)
        left.extend(f"{rel}: {p}" for p in remaining)
    return changed, left


def set_year(text: str, year: str) -> str:
    """The text with the owner's copyright year set (for files a sync seeds)."""
    lines = text.splitlines(keepends=True)
    for i, value in read_header(lines).copyright_lines:
        m = YEAR_LEAD.match(value)
        if m and HOLDER in m.group(2):
            lines[i] = lines[i].replace(value, f"{year} {HOLDER}", 1)
    return "".join(lines)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=(__doc__ or "").splitlines()[0])
    ap.add_argument("--repo", type=Path, default=Path())
    ap.add_argument("--write", action="store_true", help="insert or repair the two lines")
    ap.add_argument("--license", help="--write: the SPDX expression where nothing else says one")
    ap.add_argument("paths", nargs="*", help="--write: only these paths (globs allowed)")
    args = ap.parse_args(argv)
    root = args.repo.resolve()
    if args.write:
        changed, left = write_repo(root, args.paths or None, args.license)
        for rel in changed:
            print(f"wrote the header of {rel}")
        for line in left:
            print(f"spdx-headers: {line}")
        return 1 if left else 0
    problems, notes = check_repo(root)
    for note in notes:
        print(f"note: {note}")
    for line in problems:
        print(f"spdx-headers: {line}")
    if problems:
        print(
            f"{len(problems)} problem(s): run spdx_headers.py --write (docs/quality.md,"
            ' "Licensing headers")'
        )
        return 1
    print("licensing headers: clean")
    return 0


if __name__ == "__main__":
    sys.exit(main())
